const e = $('Entree').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.code_cle);
const SOURCES = { Toshiba: 'base officielle des codes defaut Toshiba France (Espace Pro)', Daikin: 'document officiel Daikin France SM-TS3 (autodiagnostic par code de dysfonctionnement)' };
if (!SOURCES[e.marque]) {
  return [{ json: { absent: false, resultat: 'Pas encore de table de codes defaut pour la marque ' + (e.marque || 'inconnue') + ' (Toshiba et Daikin seulement pour l instant). Ne devine pas : dis au technicien de consulter la notice de la machine ou d appeler Laurent.' } }];
}
if (!e.cle) return [{ json: { absent: false, resultat: 'Aucun code defaut fourni : demander le code exact affiche (telecommande ou LED).' } }];
const sp = s => String(s || '').toUpperCase().replace(/\s+/g, ' ').trim();
const exact = rows.filter(r => r.code_cle === e.cle);
const sous = rows.filter(r => r.code_cle !== e.cle && sp(r.code).startsWith(e.code + ' ')).slice(0, 10);
const v = new Set();
const m = e.marque === 'Toshiba' ? /^E?0*(\d{1,3})$/.exec(e.cle) : null;
if (m) { const n = m[1]; const p2 = n.padStart(2, '0'); [n, p2, 'E' + p2, 'E' + n, n.padStart(4, '0')].forEach(x => v.add(x)); }
const proches = rows.filter(r => v.has(r.code_cle) && r.code_cle !== e.cle);
const fiche = r => 'Code ' + r.code + ' : ' + r.designation + (r.notes ? '\n' + (e.marque === 'Toshiba' ? 'A verifier selon Toshiba : ' : '') + r.notes : '') + (r.notes_climatpro ? '\nNote terrain ClimatPro : ' + r.notes_climatpro : '');
const L = [];
L.push('Source : ' + SOURCES[e.marque] + ', mise a jour le ' + ((exact[0] || proches[0] || rows[0] || {}).maj || '?') + '.');
L.push('Gamme de la machine : ' + e.gamme + '. Si plusieurs fiches ou plusieurs gammes sont donnees pour ce code, ne garde que celle qui correspond a la machine.');
if (exact.length) exact.forEach(r => L.push(fiche(r)));
if (proches.length) { L.push(exact.length ? 'Meme code sous un autre affichage (selon la commande ou la gamme) :' : 'Code exact absent, mais ce code existe sous un autre affichage :'); proches.forEach(r => L.push(fiche(r))); }
if (sous.length) { L.push('Sous-codes existants (si la machine affiche un sous-code, le demander) :'); sous.forEach(r => L.push('- ' + fiche(r))); }
const absent = !exact.length && !proches.length && !sous.length;
if (absent) {
  L.length = 0;
  L.push('Code ' + e.code + ' introuvable dans la ' + SOURCES[e.marque] + '. Ne devine pas sa signification. Demande au technicien de verifier la lecture (code complet avec sous-code, affichage telecommande ou clignotements LED).' + (/Altherma/.test(e.gamme) ? ' Les codes Altherma (PAC air/eau) ne sont pas dans ce document.' : '') + ' Laurent a ete prevenu.');
}
return [{ json: { absent, resultat: L.join('\n').slice(0, 6000) } }];

const i = $input.first().json || {};
const modele = String(i.modele || '').toUpperCase().replace(/\s+/g, '').trim();
let marque = String(i.marque || '').trim();
if (/^tosh/i.test(marque)) marque = 'Toshiba';
else if (/^daik/i.test(marque)) marque = 'Daikin';
else if (/^hit/i.test(marque)) marque = 'Hitachi';
if (!marque && /^(RAK|RAC|RAD|RAF|RAI|RAM|RCI|RCD|RPI|RPK|RPC|RPF|RWM|RWD|RWH|RASC|RASM|KPI|RCUE|RHUE|RCME|RHME|RCMA|RHMA|YUTAKI)/.test(modele)) marque = 'Hitachi';
if (!marque && /^(RAS|RAV|MMY|MCY|MM[A-Z]|HWT|HWS)-?/.test(modele)) marque = 'Toshiba';
if (!marque && /^(FTX|ATX|ARX|CTX|FVX|FDX|RX[A-Z]|FBA|FCA|FFA|FHA|AZA|RZA|RZQ|FX[A-Z]|REY|RYY|RXY|EH[A-Z]|ER[A-Z]|EB[A-Z]|ED[A-Z])/.test(modele)) marque = 'Daikin';
const code = String(i.code || '').toUpperCase().replace(/^(CODE|ERREUR|ERROR)\s*/, '').replace(/[-_.]+/g, ' ').replace(/\s+/g, ' ').trim();
const cle = code.replace(/[^A-Z0-9]/g, '');
let gamme = 'inconnue (modele non fourni)';
if (marque === 'Toshiba') {
  if (/^RAS/.test(modele)) gamme = 'RAS (residentiel : muraux, multisplits)';
  else if (/^RAV/.test(modele)) gamme = 'RAV (petit tertiaire Digital Inverter : cassettes, gainables, consoles, plafonniers)';
  else if (/^(MMY|MCY|MM[A-Z])/.test(modele)) gamme = 'DRV / VRF (SMMS, MiNi-SMMS, SHRM)';
  else if (/^HW[ST]/.test(modele)) gamme = 'ESTIA (PAC air/eau)';
  else if (modele) gamme = 'non reconnue a partir du modele ' + modele;
} else if (marque === 'Daikin') {
  if (/^(FTX|ATX|ARX|CTX|FVX|FDX|RX[MPAJFCGLNT])/.test(modele)) gamme = 'RA (residentiel : muraux, consoles, multisplits)';
  else if (/^(FBA|FCA|FFA|FHA|AZA|RZA|RZQ)/.test(modele)) gamme = 'SkyAir (petit tertiaire)';
  else if (/^(FX[A-Z]|REY|RYY|RXY)/.test(modele)) gamme = 'VRV';
  else if (/^(EH[A-Z]|ER[A-Z]|EB[A-Z]|ED[A-Z])/.test(modele)) gamme = 'Altherma (PAC air/eau) : ce document Daikin ne couvre PAS les codes Altherma';
  else if (modele) gamme = 'non reconnue a partir du modele ' + modele;
}
return [{ json: { marque, code, cle, modele, gamme, code_brut: String(i.code || '').trim(), modele_brut: String(i.modele || '').trim(), demandeur: String(i.demandeur || '') } }];

const e = $('Entree').first().json;
const admins = $input.all().map(i => i.json).filter(u => u.actif && u.role === 'admin' && u.telegram_id);
const t = 'Code defaut absent de la base : ' + e.marque + ' ' + e.code + (e.modele ? ' (modele ' + e.modele + ')' : '') + ', demande par ' + (e.demandeur || '?') + '.' + (e.marque === 'Hitachi' ? '\nBase Hitachi : appli officielle airCloud Alarm Code (table codes_hitachi).' : '\nSi tu le connais, ajoute une ligne dans la Data Table codes_defaut (colonne notes_climatpro).');
return admins.map(a => ({ json: { chat_id: String(a.telegram_id), text: t } }));
